"""Ordered-sequence lookup helpers."""


def index_of(items, target):
    """Index of the FIRST occurrence of `target` in ascending `items`, or -1 if absent."""
    lo, hi = 0, len(items) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if items[mid] == target:
            return mid
        if items[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1
